/// <summary>
/// Runs <c>ARBWhereUsedPopulateService</c>; asynchronous by default because it reads the metadata of
/// all tables, EDTs, views, data entities, queries and forms.
/// </summary>
class ARBWhereUsedPopulateController extends SysOperationServiceController
{
}

Method.Source:
protected void new(IdentifierName _className = '', IdentifierName _methodName = '', SysOperationExecutionMode _executionMode = SysOperationExecutionMode::ReliableAsynchronous)
{
    super(classStr(ARBWhereUsedPopulateService), methodStr(ARBWhereUsedPopulateService, populateWhereUsed), _executionMode);
}

/// <summary>
/// Creates a new controller.
/// </summary>
/// <returns>A new <c>ARBWhereUsedPopulateController</c>.</returns>
public static ARBWhereUsedPopulateController construct()
{
    return new ARBWhereUsedPopulateController();
}

public static void main(Args _args)
{
    ARBWhereUsedPopulateController controller = ARBWhereUsedPopulateController::construct();

    controller.startOperation();
}

public LabelType parmDialogCaption(LabelType _dialogCaption = dialogCaption)
{
    // Caption is always overridden to ensure a consistent batch job description
    return "@AOTBrowser:PopulateWhereUsed";
}
